#requires -Version 5.1
<#
.SYNOPSIS
    GDebloat: Micro 11 Barebones-derived Windows image builder.
.DESCRIPTION
    Uses the full install-image file and package removal lists from the user's
    TrimKit/Micro 11 Barebones.ps1, with protected driver/audio/Store/Xbox/runtime
    exceptions. Uses Micro's takeown/icacls and direct deletion approach.
    Boot.wim and setup media are never debloated. WinSxS trimming retains live
    hardlinked components, protected runtimes, and installation metadata.
    Edge/WebView2 and WinRE are removed; automatic OS updates are disabled.
    Manual stripping is irreversible and may leave CBS servicing inconsistent.
    Final image size, installation, audio, Store and Xbox must be tested on Windows.
    Micro source SHA256: 46254253E4B18470221DFF828C7F1F5BBB0B4339C3369571AD7F4BBA9D22F20B
.PARAMETER SourceIso
    Mounted Windows media drive (F, F:, F:\), folder, or ISO path. Prompts if omitted.
.PARAMETER ImageIndex
    Source edition. Zero selects the only edition or prompts.
.PARAMETER WorkDirectory
    Parent for an isolated build folder; existing contents are never cleared.
.PARAMETER DriverDirectory
    Optional extracted signed OEM INF drivers to add to install and boot images.
.PARAMETER SizeProfile
    Compatibility parameter: Minimal runs Micro removals. Balanced is rejected;
    use an earlier revision if you need the previous balanced builder.
#>
[CmdletBinding()]
param(
    [string]$SourceIso,
    [int]$ImageIndex = 0,
    [string]$OutputIso = (Join-Path (Get-Location) 'GDebloat-Micro.iso'),
    [string]$WorkDirectory = (Join-Path $env:TEMP 'GDebloat'),
    [string]$OscdimgPath,
    [string]$DriverDirectory,
    [ValidateSet('Minimal')][string]$SizeProfile = 'Minimal'
)
$ErrorActionPreference = 'Stop'
if ([Environment]::OSVersion.Platform -ne 'Win32NT' -or -not [Environment]::Is64BitProcess) {
    throw 'Run in elevated 64-bit Windows PowerShell on Windows.'
}
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    throw 'Open Windows PowerShell as Administrator, then run this script.'
}


function Write-Header([string]$Title) {
    Write-Host ""
    Write-Host ("=" * 76) -ForegroundColor Cyan
    Write-Host "  $Title" -ForegroundColor White
    Write-Host ("=" * 76) -ForegroundColor Cyan
}

function Write-Step([string]$Message) {
    Write-Host "  [+] $Message" -ForegroundColor Green
}

function Write-Info([string]$Message) {
    Write-Host "  [*] $Message" -ForegroundColor Gray
}

function Invoke-Native([string]$File, [string[]]$Arguments, [int[]]$SuccessCodes = @(0)) {
    & $File @Arguments | Out-Host
    if ($LASTEXITCODE -notin $SuccessCodes) {
        $nativeError = New-Object System.InvalidOperationException("$File failed with exit code $LASTEXITCODE. Arguments: $($Arguments -join ' ')")
        $nativeError.Data['ExitCode'] = [int]$LASTEXITCODE
        throw $nativeError
    }
}

function Invoke-Dism([string[]]$Arguments, [int[]]$SuccessCodes = @(0, 3010)) {
    $dismExe = "$env:SystemRoot\System32\dism.exe"
    Invoke-Native $dismExe (@('/English') + $Arguments) $SuccessCodes
}


$script:EmbeddedOscdimgBase64 = @'

'@


function Get-OscdimgExecutable([string]$ExplicitPath, [string]$TargetDirectory) {
    if ($ExplicitPath -and (Test-Path -LiteralPath $ExplicitPath -PathType Leaf)) {
        return (Resolve-Path -LiteralPath $ExplicitPath).Path
    }
    $candidates = @(
        (Join-Path $PSScriptRoot 'oscdimg.exe'),
        (Join-Path (Get-Location) 'oscdimg.exe'),
        (Join-Path $PSScriptRoot 'scripts\oscdimg.exe'),
        (Join-Path $PSScriptRoot 'tools\oscdimg.exe'),
        'C:\Program Files (x86)\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\amd64\Oscdimg\oscdimg.exe',
        'C:\Program Files\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\amd64\Oscdimg\oscdimg.exe'
    )
    foreach ($c in $candidates) {
        if (Test-Path -LiteralPath $c -PathType Leaf) {
            return (Resolve-Path -LiteralPath $c).Path
        }
    }
    $cmd = Get-Command 'oscdimg.exe' -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }

    # Extract embedded Base64 oscdimg.exe
    Write-Step "Extracting embedded oscdimg.exe (ADK)..."
    $destinationDir = if ($TargetDirectory) { $TargetDirectory } else { Join-Path $env:TEMP 'TrimKit-Tools' }
    New-Item -ItemType Directory -Path $destinationDir -Force | Out-Null
    $extractedExe = Join-Path $destinationDir 'oscdimg.exe'
    
    $expectedHash = 'F5129F313ED7EB46F2677CF522E64264A225F226307ED0DDB52BB14C46E7CFDD'
    if (Test-Path -LiteralPath $extractedExe) {
        $existingHash = (Get-FileHash -LiteralPath $extractedExe -Algorithm SHA256).Hash
        if ($existingHash -ieq $expectedHash) {
            return $extractedExe
        }
    }

    $bytes = [Convert]::FromBase64String($script:EmbeddedOscdimgBase64)
    [IO.File]::WriteAllBytes($extractedExe, $bytes)

    $hash = (Get-FileHash -LiteralPath $extractedExe -Algorithm SHA256).Hash
    if ($hash -ine $expectedHash) {
        throw "Extracted oscdimg.exe failed integrity verification. Expected: $expectedHash, Got: $hash"
    }

    return $extractedExe
}


function Get-OfflineDriverInventory([string]$MountPath) {
    $drivers = @(Get-WindowsDriver -Path $MountPath -All -ErrorAction Stop)
    if ($drivers.Count -eq 0) { throw "No drivers returned for mounted image: $MountPath" }
    foreach ($driver in $drivers) {
        [pscustomobject]@{
            Key = ("{0}|{1}|{2}" -f $driver.Driver, $driver.OriginalFileName, $driver.Version).ToLowerInvariant()
            Inf = [IO.Path]::GetFileName($driver.OriginalFileName)
            Provider = [string]$driver.ProviderName
            Class = [string]$driver.ClassName
            Version = [string]$driver.Version
        }
    }
}

function Assert-DriversPreserved([object[]]$Before, [object[]]$After, [string]$Label) {
    $afterKeys = @{}
    foreach ($driver in $After) { $afterKeys[$driver.Key] = $true }
    $missing = @($Before | Where-Object { -not $afterKeys.ContainsKey($_.Key) })
    if ($missing.Count -gt 0) {
        throw "$Label lost source drivers during servicing: $($missing.Inf -join ', ')"
    }
}


# Shared runtimes and the requested device/application paths are exceptions to Micro.
$ProtectedAppPatterns = @(
    'Microsoft.WindowsStore*', 'Microsoft.StorePurchaseApp*', 'Microsoft.DesktopAppInstaller*',
    'Microsoft.GamingApp*', 'Microsoft.GamingServices*', 'Microsoft.Xbox*',
    'Microsoft.VCLibs*', 'Microsoft.NET.Native*', 'Microsoft.UI.Xaml*',
    'Microsoft.WindowsAppRuntime*', 'Microsoft.Services.Store.Engagement*',
    'Microsoft.AV1*', 'Microsoft.AVC*', 'Microsoft.HEVC*', 'Microsoft.HEIF*',
    'Microsoft.VP9*', 'Microsoft.WebMedia*', 'Microsoft.Webp*',
    'Microsoft.ApplicationCompatibilityEnhancements*', 'Microsoft.SecHealthUI*'
)
function Test-MicroProtectedApp([string]$Name) {
    foreach ($pattern in $ProtectedAppPatterns) { if ($Name -like $pattern) { return $true } }
    return $false
}
function Test-MicroProtectedPackage([string]$Name) {
    return $Name -match '(?i)(Ethernet|Wifi|Wlan|Audio|Xbox|Gaming|Appx|Store|VCLibs|NetFx|Net-Framework|DotNet|Installer|BitLocker|TPM-WMI|Hello-BioEnrollment)'
}
function Test-MicroProtectedPath([string]$RelativePath) {
    $path = $RelativePath.Replace('/', '\').TrimStart('\')
    if ($path -match '(?i)^Windows\\(INF|servicing|Microsoft\.NET|Installer|Registration)(\\|$)') { return $true }
    if ($path -match '(?i)^Windows\\assembly(\\|$)' -and $path -notmatch '(?i)\\NativeImages_') { return $true }
    if ($path -match '(?i)^Windows\\(System32|SysWOW64)\\(DriverStore|drivers|CatRoot|catroot2|Dism|WindowsPowerShell|WinMetadata)(\\|$)') { return $true }
    if ($path -match '(?i)^Windows\\(Boot|WinSxS)(\\|$)') { return $true }
    if ($path -match '(?i)^Windows\\SystemApps\\[^\\]*(Client\.(CBS|Core|Photon)|WindowsAppRuntime|ShellExperience|StartMenu|CloudExperience|AAD|AccountsControl|Xbox|Store|Gaming)') { return $true }
    if ($path -match '(?i)^Program Files(?: \(x86\))?\\(WindowsApps|Windows Defender|Windows NT\\Accessories|Common Files\\(Microsoft Shared\\(VC|VBA)|System|microsoft shared\\ink))(\\|$)') { return $true }
    if ($path -match '(?i)^ProgramData\\Microsoft\\(Windows\\AppRepository|Windows\\ClipSVC|Crypto|Windows Defender)(\\|$)') { return $true }
    $leaf = ($path -split '\\')[-1]
    if ($leaf -match '(?i)^(audio|audios|mmdevapi|wdma|portcls|hdaudio|avrt|mmcss|mmc|msacm|msadp|msg711|msgsm|imaadp|l3code|dsound|devenum|quartz|msdmo|xaudio|xinput|xact|x3daudio|winmm|mmsys|ksuser|spatialaudio|appx|appmodel|appinstaller|store|clip|licens|xbox|xbl|gaming|gamebar|webaccount|microsoftaccount|profapi|userenv|token|aad|wlid|cloudap|cred|crypt|bcrypt|ncrypt|wintrust|msi|msiexec|msxml|combase|ole|rpc|kernel|ntdll|user32|gdi|dwm|dxgi|d3d|dxil|mf|wmv|wmp|winhttp|wininet|urlmon|iertutil|jscript|chakra|vcruntime|msvcp|ucrt|concrt|ws2|dns|dhcp|nla|net|tcp|iphlp|nsisvc|nsi|winlogon|logonui|lsass|sam|sechost|advapi|cfgmgr|setupapi|dism|drv|wimg|imagehlp|bcd|winload|winresume|boot|wlan|ras|dot3|eaphost|schannel|spp|powershell)') { return $true }
    return $false
}
function Set-MicroOwnership([string]$Path) {
    # Match Micro's best-effort bulk ownership pass, retaining its diagnostics.
    # A failure here is reported; individual file removal results remain explicit.
    foreach ($command in @(
        @{ File = 'takeown.exe'; Args = @('/F', $Path, '/A', '/R', '/D', 'Y') },
        @{ File = 'icacls.exe'; Args = @($Path, '/grant', '*S-1-5-32-544:(OI)(CI)F', '/T', '/C', '/L', '/Q') }
    )) {
        $previousPreference = $ErrorActionPreference
        try {
            $ErrorActionPreference = 'Continue'
            $arguments = $command.Args
            & $command.File @arguments > $null 2>&1
            $ownershipExit = $LASTEXITCODE
        } finally { $ErrorActionPreference = $previousPreference }
        if ($ownershipExit -ne 0) { Write-Warning "$($command.File) reported $ownershipExit for $Path; optional deletion outcomes will be reported individually." }
    }
}
function Remove-MicroTargets([string]$MountPath, [string[]]$RelativePaths) {
    foreach ($relative in $RelativePaths) {
        if (Test-MicroProtectedPath $relative) { continue }
        $target = Join-Path $MountPath $relative
        if (-not (Test-Path -LiteralPath $target)) { continue }
        try {
            Remove-Item -LiteralPath $target -Recurse -Force -ErrorAction Stop
        } catch {
            Write-Warning "Micro optional file removal incomplete: $relative. $($_.Exception.Message)"
            [pscustomobject]@{ Path = $relative; Outcome = 'RetainedOrPartial'; Error = $_.Exception.Message }
            continue
        }
        [pscustomobject]@{ Path = $relative; Outcome = 'Removed'; Error = $null }
    }
}
function Initialize-MicroLinkQuery {
    if ('GDebloat.MicroFileLinks' -as [type]) { return }
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
namespace GDebloat {
  public static class MicroFileLinks {
    [StructLayout(LayoutKind.Sequential)] struct Info {
      public uint Attributes;
      public System.Runtime.InteropServices.ComTypes.FILETIME Creation, Access, Write;
      public uint Volume, SizeHigh, SizeLow, Links, IndexHigh, IndexLow;
    }
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
    static extern SafeFileHandle CreateFile(string path, uint access, uint share, IntPtr security,
      uint creation, uint flags, IntPtr template);
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool GetFileInformationByHandle(SafeFileHandle handle, out Info info);
    public static uint Count(string path) {
      using (var handle = CreateFile(path, 0, 7, IntPtr.Zero, 3, 0x02200000, IntPtr.Zero)) {
        Info info;
        if (handle.IsInvalid || !GetFileInformationByHandle(handle, out info))
          throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
        return info.Links;
      }
    }
  }
}
'@
}
function Get-MicroLinkCount([string]$Path) { return [GDebloat.MicroFileLinks]::Count($Path) }
function Test-MicroKeepComponent([string]$Name, [object[]]$Files) {
    # Micro's small keep list is expanded for active files and requested dependencies.
    if ($Name -notmatch '^(amd64|x86|wow64|msil|arm64)_') { return $true }
    if ($Name -match '(?i)(servicingstack|\.vc\d+\.|common-controls|gdiplus|dotnet|netfx|net-framework|clr|mscore|audio|mmdev|mmcss|directx|d3d|dxgi|appx|appmodel|store|xbox|gaming|clip|licens|installer|msi|ethernet|realtek|intel|tcpip|ndis|network|wlan|winsock)') { return $true }
    foreach ($file in $Files) {
        try { if ((Get-MicroLinkCount $file.FullName) -gt 1) { return $true } }
        catch { return $true } # Unknown link state is not evidence that a component is unused.
    }
    return $false
}
function Invoke-MicroWinSxSTrim([string]$MountPath) {
    $root = Join-Path $MountPath 'Windows\WinSxS'
    $removedCount = 0
    foreach ($component in @(Get-ChildItem -LiteralPath $root -Directory -Force)) {
        if ($component.Attributes -band [IO.FileAttributes]::ReparsePoint) { continue }
        if (Test-MicroKeepComponent $component.Name @()) { continue }
        try { $files = @(Get-ChildItem -LiteralPath $component.FullName -Recurse -File -Force -ErrorAction Stop) }
        catch { Write-Warning "Retained component with unreadable inventory: $($component.Name)"; continue }
        if (Test-MicroKeepComponent $component.Name $files) { continue }
        # Direct removal like Micro, limited to unlinked/unprotected component payloads.
        try { Remove-Item -LiteralPath $component.FullName -Recurse -Force -ErrorAction Stop; $removedCount++ }
        catch { Write-Warning "Retained component payload: $($component.Name). $($_.Exception.Message)" }
    }
    return $removedCount
}
function Invoke-MicroReg([string[]]$Arguments) { Invoke-Native 'reg.exe' $Arguments }

