    'Microsoft-Windows-Wifi-Client-Intel-Netwew01-FOD-Package~'
    'Microsoft-Windows-Wifi-Client-Marvel-Mrvlpcie8897-FOD-Package~'
    'Microsoft-Windows-InternetExplorer-Optional-Package~'
    'Microsoft-Windows-Kernel-LA57-FoD-Package~'
    'Microsoft-Windows-PowerShell-ISE-FOD-Package-wow64.cab'
    'Microsoft-Windows-Wifi-Client-Intel-Netwtw04-FOD-Package~'
    'Microsoft-Windows-Wifi-Client-Realtek-Rtwlane13-FOD-Package~'
    'Microsoft-Windows-Ethernet-Client-Intel-E2f68-FOD-Package~'
    'Microsoft-Windows-LanguageFeatures-TextToSpeech-en-us-Package~'
    'Microsoft-Windows-SmbDirect-FOD-Package~'
    'Microsoft-Windows-TabletPCMath-Package~'
    'Microsoft-Windows-Wifi-Client-Intel-Netwlv64-FOD-Package~'
    'Microsoft-Windows-Wifi-Client-Realtek-Rtl8192se-FOD-Package~'
    'Microsoft-Windows-Wifi-Client-Realtek-Rtwlane01-FOD-Package~'
    'Microsoft-Windows-DirectoryServices-ADAM-Client-FOD-Package~'
    'Microsoft-Windows-EnterpriseClientSync-Host-FOD-Package~'
    'Microsoft-Windows-Hello-Face-Package~'
    'Microsoft-Windows-MediaPlayer-Package-wow64.cab'
    'Microsoft-Windows-SimpleTCP-FOD-Package~'
    'Microsoft-Windows-Wifi-Client-Intel-Netwtw06-FOD-Package~'
    'OpenSSH-Client-Package~'
    'Microsoft-Edge-WebView-FOD-Package~'
    'Microsoft-Windows-Ethernet-Client-Realtek-Rtcx21x64-FOD-Package~'
    'Microsoft-Windows-ProjFS-OptionalFeature-FOD-Package~'
    'Microsoft-Windows-StepsRecorder-Package~'
    'Microsoft-Windows-TerminalServices-AppServer-Client-FOD-Package-wow64.cab'
    'Microsoft-Windows-Wifi-Client-Intel-Netwbw02-FOD-Package~'
    'Microsoft-Windows-Wifi-Client-Intel-Netwsw00-FOD-Package~'
    'Microsoft-Windows-Wifi-Client-Ralink-Netr28x-FOD-Package~'
    'Microsoft-Windows-WMIC-FoD-Package-wow64.cab'
    'Microsoft-Windows-Ethernet-Client-Intel-E1i68x64-FOD-Package~'
    'Microsoft-Windows-LanguageFeatures-Handwriting-en-us-Package~'
    'Microsoft-Windows-LanguageFeatures-Speech-en-us-Package~'
    'Microsoft-Windows-InternetExplorer-Optional-Package~31bf3856ad364e35'
    'Microsoft-Windows-Kernel-LA57-FoD-Package~31bf3856ad364e35~amd64'
    'Microsoft-Windows-LanguageFeatures-Handwriting-$languageCode-Package~31bf3856ad364e35'
    'Microsoft-Windows-LanguageFeatures-Speech-$languageCode-Package~31bf3856ad364e35'
    'Microsoft-Windows-LanguageFeatures-TextToSpeech-$languageCode-Package~31bf3856ad364e35'
    'Microsoft-Windows-MediaPlayer-Package~31bf3856ad364e35'
    'Windows-Defender-Client-Package~31bf3856ad364e35~'
    'Microsoft-Windows-WordPad-FoD-Package~'
    'Microsoft-Windows-MSPaint-FoD-Package~'
    'Microsoft-Windows-SnippingTool-FoD-Package~'
    'Microsoft-Windows-Xps-Xps-Viewer-Opt-Package~'
    '*IME-ja-jp*'
    '*IME-ko-kr*'
    '*IME-zh-cn*'
    '*IME-zh-tw*'
    'Microsoft-Windows-Hello-BioEnrollment-Package~'
    'Microsoft-Windows-BitLocker-DriveEncryption-FVE-Package~'
    'Microsoft-Windows-TPM-WMI-Provider-Package~'
    'Microsoft-Windows-Narrator-App-Package~'
    'Microsoft-Windows-Magnifier-App-Package~'
)

Write-Header 'GDEBLOAT - MICRO 11 BASE WITH DRIVER / AUDIO / STORE / XBOX EXCEPTIONS'
if (-not $SourceIso) { $SourceIso = Read-Host 'Windows ISO path or mounted drive (e.g. F)' }
$SourceIso = $SourceIso.Trim('"').Trim("'")
if ($SourceIso -match '^[A-Za-z]:?\\?$') { $SourceIso = $SourceIso.Substring(0, 1) + ':\' }
$SourceIso = (Resolve-Path -LiteralPath $SourceIso -ErrorAction Stop).Path
$OutputIso = [IO.Path]::GetFullPath($OutputIso)
if (Test-Path -LiteralPath $OutputIso) { throw "Output exists; choose another -OutputIso: $OutputIso" }
if ($SourceIso -ieq $OutputIso) { throw 'Source and output ISO must differ.' }
if ($DriverDirectory) {
    $DriverDirectory = (Resolve-Path -LiteralPath $DriverDirectory).Path
    if (-not (Get-ChildItem -LiteralPath $DriverDirectory -Filter '*.inf' -File -Recurse)) {
        throw 'DriverDirectory must contain extracted signed INF driver packages.'
    }
}
$workRoot = [IO.Path]::GetPathRoot([IO.Path]::GetFullPath($WorkDirectory))
$volume = New-Object IO.DriveInfo($workRoot)
if ($volume.DriveFormat -ne 'NTFS' -or $volume.AvailableFreeSpace -lt 20GB) {
    throw 'Use an NTFS work volume with at least 20 GB free.'
}
$work = Join-Path ([IO.Path]::GetFullPath($WorkDirectory)) ('Micro-' + [guid]::NewGuid().ToString('N'))
$media = Join-Path $work 'media'
$mount = Join-Path $work 'scratchdir'
$bootMount = Join-Path $work 'bootmount'
New-Item -ItemType Directory -Path $media, $mount, $bootMount -Force | Out-Null
$mountedInstall = $false
$mountedBoot = $false
$ownsIso = $false
$transcribing = $false
$completed = $false
try {
    Start-Transcript -Path (Join-Path $work 'build.log') | Out-Null
    $transcribing = $true
    $source = $SourceIso
    if (Test-Path -LiteralPath $SourceIso -PathType Leaf) {
        $diskImage = Get-DiskImage -ImagePath $SourceIso -ErrorAction SilentlyContinue
        if (-not $diskImage -or -not $diskImage.Attached) {
            $diskImage = Mount-DiskImage -ImagePath $SourceIso -PassThru
            $ownsIso = $true
        }
        $sourceVolume = $diskImage | Get-Volume
        if (-not $sourceVolume.DriveLetter) { throw 'Mounted ISO has no drive letter.' }
        $source = "$($sourceVolume.DriveLetter):\"
    }
    $sourceWim = Join-Path $source 'sources\install.wim'
    $sourceEsd = Join-Path $source 'sources\install.esd'
    $sourceImage = if (Test-Path -LiteralPath $sourceWim) { $sourceWim } elseif (Test-Path -LiteralPath $sourceEsd) { $sourceEsd } else { throw 'No install.wim/install.esd in source media.' }
    $images = @(Get-WindowsImage -ImagePath $sourceImage)
    $indexes = @($images | ForEach-Object { [int]$_.ImageIndex })
    if (-not $indexes.Count) { throw 'Source contains no installation images.' }
    if ($ImageIndex -notin $indexes) {
        if ($images.Count -eq 1) { $ImageIndex = [int]$images[0].ImageIndex }
        else {
            $images | Format-Table ImageIndex, ImageName | Out-Host
            do {
                $inputIndex = Read-Host "Edition index [$($indexes -join ', ')]"
                $ImageIndex = 0
                [void][int]::TryParse($inputIndex, [ref]$ImageIndex)
            } until ($ImageIndex -in $indexes)
        }
    }
    $details = Get-WindowsImage -ImagePath $sourceImage -Index $ImageIndex
    if ([string]$details.Architecture -notin @('9', 'amd64', 'x64')) { throw 'This adapted Micro build supports x64 source images only.' }
    $architecture = 'amd64'
    Write-Step "Using [$ImageIndex] $($details.ImageName)"
    $sourceBoot = Join-Path $source 'sources\boot.wim'
    $bootHashBefore = (Get-FileHash -LiteralPath $sourceBoot -Algorithm SHA256).Hash
    $OscdimgPath = Get-OscdimgExecutable -ExplicitPath $OscdimgPath -TargetDirectory $work
    Initialize-MicroLinkQuery
    Write-Header 'MICRO: COPY MEDIA, EXPORT SELECTED EDITION AND MOUNT'
    Invoke-Native 'robocopy.exe' @($source, $media, '/E', '/COPY:DAT', '/DCOPY:DAT', '/R:1', '/W:1', '/NFL', '/NDL',
        '/XF', 'install*.wim', 'install*.esd', 'install*.swm', 'autounattend.xml') @(0,1,2,3,4,5,6,7)
    $wim = Join-Path $work 'install_working.wim'
    Invoke-Dism @('/Export-Image', "/SourceImageFile:$sourceImage", "/SourceIndex:$ImageIndex", "/DestinationImageFile:$wim", '/Compress:max', '/CheckIntegrity')
    Invoke-Dism @('/Mount-Image', "/ImageFile:$wim", '/Index:1', "/MountDir:$mount", '/CheckIntegrity')
    $mountedInstall = $true
    $sourceDrivers = @(Get-OfflineDriverInventory $mount)
    if ($DriverDirectory) { Invoke-Dism @("/Image:$mount", '/Add-Driver', "/Driver:$DriverDirectory", '/Recurse') }

    # Micro takes ownership before bulk native-backed file removal.
    foreach ($relative in @('Program Files', 'Program Files (x86)', 'ProgramData', 'Windows')) {
        $path = Join-Path $mount $relative
        if (Test-Path -LiteralPath $path) { Set-MicroOwnership $path }
    }
    Write-Header 'MICRO: REMOVE PROVISIONED APPS EXCEPT PROTECTED PACKAGES'
    $appsBefore = @(Get-AppxProvisionedPackage -Path $mount)
    $appResults = @()
    foreach ($app in $appsBefore) {
        if (Test-MicroProtectedApp $app.DisplayName) { continue }
        try {
            Remove-AppxProvisionedPackage -Path $mount -PackageName $app.PackageName -ErrorAction Stop | Out-Null
            $appResults += [pscustomobject]@{ Name = $app.PackageName; Outcome = 'Removed'; Error = $null }
        } catch {
            Write-Warning "Optional AppX retained: $($app.PackageName). $($_.Exception.Message)"
            $appResults += [pscustomobject]@{ Name = $app.PackageName; Outcome = 'Retained'; Error = $_.Exception.Message }
        }
    }
    Write-Header 'MICRO: REMOVE TARGET PACKAGES, PRESERVING NETWORK / AUDIO / RUNTIMES'
    $packageResults = @()
    $packages = @(Get-WindowsPackage -Path $mount)
    foreach ($package in $packages) {
        if ([string]$package.PackageState -notin @('Installed', 'Staged')) { continue }
        $name = [string]$package.PackageName
        if (Test-MicroProtectedPackage $name) { continue }
        $selected = $false
        foreach ($pattern in $MicroPackagePatterns) {
            $pattern = $pattern.Replace('$languageCode', '*') -replace '(?i)\.cab$', ''
            if ($name -like ($pattern + '*')) { $selected = $true; break }
        }
        if (-not $selected) { continue }
        try {
            Invoke-Dism @("/Image:$mount", '/Remove-Package', "/PackageName:$name", '/NoRestart')
            $packageResults += [pscustomobject]@{ Name = $name; Outcome = 'Removed'; ExitCode = 0 }
        } catch {
            $code = $_.Exception.Data['ExitCode']
            if ($null -eq $code) { throw }
            Write-Warning "Micro optional package retained: $name (DISM $code)"
            $packageResults += [pscustomobject]@{ Name = $name; Outcome = 'Retained'; ExitCode = $code }
        }
    }
    Write-Header 'MICRO: BULK INSTALL-IMAGE FILE REMOVAL WITH PROTECTED EXCEPTIONS'
    $eligiblePaths = @($MicroRemovalPaths | Where-Object { -not (Test-MicroProtectedPath $_) })
    Write-Step "Micro file targets: $($MicroRemovalPaths.Count); eligible after protections: $($eligiblePaths.Count)"
    $fileResults = @(Remove-MicroTargets $mount $eligiblePaths)
    # Explicit Micro removals which appear outside its large architecture-aware list.
    $extraPaths = @(
        'Program Files (x86)\Microsoft\Edge', 'Program Files (x86)\Microsoft\EdgeCore',
        'Program Files (x86)\Microsoft\EdgeUpdate', 'Program Files (x86)\Microsoft\EdgeWebView',
        'Program Files\Microsoft\Edge', 'Program Files\Microsoft\EdgeCore',
        'Program Files\Microsoft\EdgeUpdate', 'Program Files\Microsoft\EdgeWebView',
        'Windows\System32\Microsoft-Edge-WebView', 'Windows\SysWOW64\Microsoft-Edge-WebView',
        'Windows\System32\OneDriveSetup.exe', 'Windows\SysWOW64\OneDriveSetup.exe',
        'Windows\System32\Recovery\winre.wim'
    )
    $nativeImages = Join-Path $mount 'Windows\assembly'
    if (Test-Path -LiteralPath $nativeImages) {
        $extraPaths += @(Get-ChildItem -LiteralPath $nativeImages -Directory -Filter 'NativeImages_*' |
            ForEach-Object { 'Windows\assembly\' + $_.Name })
    }
    $fileResults += @(Remove-MicroTargets $mount $extraPaths)
    Write-Header 'MICRO: TRIM WINSXS PAYLOADS WITHOUT REMOVING LIVE DEPENDENCIES'
    $removedComponents = Invoke-MicroWinSxSTrim $mount
    Write-Step "Unused/unprotected component directories removed: $removedComponents"

    # Keep Micro's user-requested policy changes without its blind registry sweeps.
    $systemLoaded = $false
    $softwareLoaded = $false
    try {
        Invoke-MicroReg @('load', 'HKLM\GDebloatMicroSYSTEM', (Join-Path $mount 'Windows\System32\config\SYSTEM'))
        $systemLoaded = $true
        Invoke-MicroReg @('load', 'HKLM\GDebloatMicroSOFTWARE', (Join-Path $mount 'Windows\System32\config\SOFTWARE'))
        $softwareLoaded = $true
        foreach ($service in @('Audiosrv', 'AudioEndpointBuilder', 'MMCSS')) {
            Invoke-MicroReg @('add', "HKLM\GDebloatMicroSYSTEM\ControlSet001\Services\$service", '/v', 'Start', '/t', 'REG_DWORD', '/d', '2', '/f')
        }
        foreach ($service in @('AppXSvc', 'ClipSVC', 'BITS', 'wuauserv', 'InstallService', 'XblAuthManager', 'XblGameSave', 'XboxNetApiSvc')) {
            $key = "HKLM\GDebloatMicroSYSTEM\ControlSet001\Services\$service"
            & reg.exe query $key > $null 2>&1
            if ($LASTEXITCODE -eq 0) {
                Invoke-MicroReg @('add', $key, '/v', 'Start', '/t', 'REG_DWORD', '/d', '3', '/f')
            }
        }
        Invoke-MicroReg @('add', 'HKLM\GDebloatMicroSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU', '/v', 'NoAutoUpdate', '/t', 'REG_DWORD', '/d', '1', '/f')
        Invoke-MicroReg @('add', 'HKLM\GDebloatMicroSOFTWARE\Microsoft\Windows\CurrentVersion\ReserveManager', '/v', 'ShippedWithReserves', '/t', 'REG_DWORD', '/d', '0', '/f')
    } finally {
        $unloadFailures = @()
        foreach ($entry in @(@{ Loaded = $softwareLoaded; Name = 'GDebloatMicroSOFTWARE' }, @{ Loaded = $systemLoaded; Name = 'GDebloatMicroSYSTEM' })) {
            if (-not $entry.Loaded) { continue }
            $unloaded = $false
            for ($attempt = 0; $attempt -lt 15; $attempt++) {
                & reg.exe unload "HKLM\$($entry.Name)" > $null 2>&1
                if ($LASTEXITCODE -eq 0) { $unloaded = $true; break }
                [GC]::Collect(); [GC]::WaitForPendingFinalizers()
                Start-Sleep -Milliseconds 400
            }
            if (-not $unloaded) { $unloadFailures += $entry.Name }
        }
        if ($unloadFailures.Count) { throw "Could not unload offline hives: $($unloadFailures -join ', ')" }
    }
    $restoreNotes = @'
Micro-based GDebloat removed Edge and WebView2. To restore them later, download
Microsoft's full x64 Edge installer from https://www.microsoft.com/edge/business/download
and the WebView2 Evergreen Standalone Runtime from
https://developer.microsoft.com/microsoft-edge/webview2/
Install both as Administrator and reboot. Installer/framework files are protected,
but browser restoration and Xbox/Store functionality must be tested on this image.
'@
    $notes = Join-Path $mount 'Windows\Setup\Scripts\GDebloat-RestoreBrowsers.txt'
    New-Item -ItemType Directory -Path (Split-Path -Parent $notes) -Force | Out-Null
    [IO.File]::WriteAllText($notes, $restoreNotes)
    # Verify requested source drivers and protected provisioned apps before commit.
    $finalDrivers = @(Get-OfflineDriverInventory $mount)
    Assert-DriversPreserved $sourceDrivers $finalDrivers 'Micro install image'
    $appsAfter = @(Get-AppxProvisionedPackage -Path $mount)
    foreach ($app in $appsBefore) {
        if ((Test-MicroProtectedApp $app.DisplayName) -and $app.PackageName -notin @($appsAfter.PackageName)) {
            throw "Protected AppX package lost: $($app.PackageName)"
        }
    }
    $networkDrivers = @($finalDrivers | Where-Object { $_.Class -eq 'Net' -and $_.Provider -match 'Intel|Realtek' })
    if (-not $networkDrivers.Count) { Write-Warning 'No Intel/Realtek network packages detected. Supply matching OEM drivers with -DriverDirectory.' }
    Write-Header 'MICRO: COMMIT AND EXPORT SINGLE-EDITION RECOVERY-COMPRESSED ESD'
    Invoke-Dism @('/Unmount-Image', "/MountDir:$mount", '/Commit', '/CheckIntegrity')
    $mountedInstall = $false
    $destEsd = Join-Path $media 'sources\install.esd'
    Invoke-Dism @('/Export-Image', "/SourceImageFile:$wim", '/SourceIndex:1', "/DestinationImageFile:$destEsd", '/Compress:recovery', '/CheckIntegrity')
    $exported = @(Get-WindowsImage -ImagePath $destEsd)
    if ($exported.Count -ne 1 -or $exported[0].ImageIndex -ne 1) { throw 'Invalid final install.esd index layout.' }
    $esdBytes = (Get-Item -LiteralPath $destEsd).Length
    $esdHash = (Get-FileHash -LiteralPath $destEsd -Algorithm SHA256).Hash
    if ($esdBytes -ge 4GB) { Write-Warning 'install.esd exceeds FAT32 file limits. Use Rufus NTFS/UEFI:NTFS.' }
    # Micro drops optional NetFx3 source media after image servicing.
    $sxs = Join-Path $media 'sources\sxs'
    if (Test-Path -LiteralPath $sxs) { Remove-Item -LiteralPath $sxs -Recurse -Force }

    # No Micro boot-image deletion, component pruning, registry sweeping, or setup-file cleanup.
    $bootWim = Join-Path $media 'sources\boot.wim'
    if ((Get-FileHash -LiteralPath $bootWim -Algorithm SHA256).Hash -ne $bootHashBefore) { throw 'Staged boot.wim differs from source before driver injection.' }
    if ($DriverDirectory) {
        (Get-Item -LiteralPath $bootWim).IsReadOnly = $false
        foreach ($bootImage in @(Get-WindowsImage -ImagePath $bootWim)) {
            Invoke-Dism @('/Mount-Image', "/ImageFile:$bootWim", "/Index:$($bootImage.ImageIndex)", "/MountDir:$bootMount")
            $mountedBoot = $true
            $bootDriversBefore = @(Get-OfflineDriverInventory $bootMount)
            Invoke-Dism @("/Image:$bootMount", '/Add-Driver', "/Driver:$DriverDirectory", '/Recurse')
            Assert-DriversPreserved $bootDriversBefore @(Get-OfflineDriverInventory $bootMount) 'Micro boot image'
            Invoke-Dism @('/Unmount-Image', "/MountDir:$bootMount", '/Commit', '/CheckIntegrity')
            $mountedBoot = $false
        }
    }
    $bios = Join-Path $media 'boot\etfsboot.com'
    $uefi = Join-Path $media 'efi\microsoft\boot\efisys.bin'
    foreach ($file in @($bios, $uefi, (Join-Path $media 'sources\setup.exe'))) {
        if (-not (Test-Path -LiteralPath $file)) { throw "Required setup file missing: $file" }
    }
    New-Item -ItemType Directory -Path (Split-Path -Parent $OutputIso) -Force | Out-Null
    Invoke-Native $OscdimgPath @('-m', '-o', '-u2', '-udfver102', '-lGDEBLOAT', "-bootdata:2#p0,e,b$bios#pEF,e,b$uefi", $media, $OutputIso)
    if (-not (Test-Path -LiteralPath $OutputIso) -or (Get-Item -LiteralPath $OutputIso).Length -eq 0) { throw 'ISO creation produced no output.' }
    $report = [ordered]@{
        Builder = 'GDebloat - Micro 11 Barebones adapted'
        MicroSourceSHA256 = '46254253E4B18470221DFF828C7F1F5BBB0B4339C3369571AD7F4BBA9D22F20B'
        SourceEdition = $details.ImageName
        SourceVersion = [string]$details.Version
        MicroFileTargetCount = $MicroRemovalPaths.Count
        EligibleFileTargetCount = $eligiblePaths.Count
        AppResults = @($appResults)
        PackageResults = @($packageResults)
        FileResults = @($fileResults)
        RemovedComponentDirectories = $removedComponents
        DriverInventoryPreserved = $true
        IntelRealtekNetworkDrivers = @($networkDrivers)
        BootImageUnchanged = (-not $DriverDirectory)
        StoreXboxAudioTested = $false
        BrowserRestoreTested = $false
        WindowsServicingSupported = $false
        InstallImageBytes = $esdBytes
        InstallImageSHA256 = $esdHash
        InstallImageTargetMet = ($esdBytes -le 1000000000)
        OutputIso = $OutputIso
        OutputIsoBytes = (Get-Item -LiteralPath $OutputIso).Length
        OutputIsoSHA256 = (Get-FileHash -LiteralPath $OutputIso -Algorithm SHA256).Hash
    }
    $report | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath "$OutputIso.report.json" -Encoding UTF8
    $completed = $true
    Write-Header 'MICRO BUILD COMPLETE'
    Write-Host "ISO: $OutputIso"
    Write-Host ("Final install.esd: {0:N3} GiB. Report: {1}.report.json" -f ($esdBytes / 1GB), $OutputIso)
    Write-Warning 'Manual Micro stripping can affect servicing and application dependencies. Boot, installation, audio, Store, Xbox and later browser installation require Windows validation. A 1 GB image is not guaranteed.'
} finally {
    if ($mountedBoot) { try { Invoke-Dism @('/Unmount-Image', "/MountDir:$bootMount", '/Discard') } catch { Write-Warning $_.Exception.Message } }
    if ($mountedInstall) { try { Invoke-Dism @('/Unmount-Image', "/MountDir:$mount", '/Discard') } catch { Write-Warning $_.Exception.Message } }
    if ($ownsIso) { Dismount-DiskImage -ImagePath $SourceIso | Out-Null }
    if ($transcribing) { Stop-Transcript | Out-Null }
    if ($completed) { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue }
    else { Write-Warning "Build failed; files and transcript retained at $work" }
}
